package com.codepilot1c.core.tools.development;
import java.util.*;import java.util.concurrent.CompletableFuture;import com.google.gson.Gson;import com.codepilot1c.core.tools.*;import com.codepilot1c.core.edt.debug.*;import com.codepilot1c.core.mcp.host.*;
@ToolMeta(name="edt_debug_targets",category="diagnostics",mutating=true,tags={"workspace","edt"})
public final class EdtDebugTargetsTool extends AbstractTool {
 public String getDescription(){return "Native debug target TYPES and guarded debug launch decisions. list(project) gives live target IDs/current/supported types. preview(project,target_id,types) -> apply(expected_plan_sha256) saves prior settings_change_id; restore_preview/restore restores only unchanged settings on the same target/epoch. Unknown or manual changes block restoration; shared targets of another project refused. Areas/breakpoints/global port are not changed. launch(project,configuration_name,dry_run) previews; actual false additionally requires idempotency_key. decision_policy=ask(default) returns awaiting_decision at NOT_EQUAL with typed choices/commands; launch_decide explicitly chooses update_and_launch or cancel. task_authorized_update opts into updating THIS project/base only when user task authorizes it. No global approve-all. Save debug_launch_id/job_id; launch_status observes original, never replay/new key after unknown. SDK modal questions in a running launch are exposed by edt_update_control. stop_owned(project,session_id) closes only a Bridge-owned debug session. Prepare separate local port with edt_debug_configure in isolated EDT. Subject type selection is not proof a running subject attached; inspect threads/stack separately. Launch success is not test acceptance.";}
 public String getParameterSchema(){return """
 {"type":"object","additionalProperties":false,"required":["action"],"properties":{"action":{"enum":["list","preview","apply","status","restore_preview","restore","launch","launch_status","launch_decide","stop_owned"]},"project":{"type":"string"},"target_id":{"type":"string"},"types":{"type":"array","maxItems":32,"uniqueItems":true,"items":{"type":"string","pattern":"^[A-Z_]{1,64}$"}},"configuration_name":{"type":"string"},"dry_run":{"type":"boolean","default":true},"idempotency_key":{"type":"string","maxLength":256},"decision_policy":{"enum":["ask","task_authorized_update"],"default":"ask"},"debug_launch_id":{"type":"string"},"choice":{"enum":["update_and_launch","cancel"]},"expected_decision_sha256":{"type":"string","pattern":"^[a-f0-9]{64}$"},"session_id":{"type":"string"},"settings_change_id":{"type":"string"},"expected_plan_sha256":{"type":"string","pattern":"^[a-f0-9]{64}$"}}}
 """;}
 private static void requireUpdateExposure(){if(!new DefaultMcpToolExposurePolicy(McpHostConfigStore.getInstance().load()).isExposed("edt_infobase_refresh"))throw new IllegalStateException("Database update operation unavailable");}
 protected CompletableFuture<ToolResult> doExecute(ToolParameters p){return CompletableFuture.supplyAsync(()->{try{String a=p.requireString("action");var keys=new HashSet<>(p.getRaw().keySet());keys.remove("action");Set<String> fields=switch(a){case "list"->Set.of("project");case "preview"->Set.of("project","target_id","types");case "apply"->Set.of("project","target_id","types","expected_plan_sha256");case "status","restore_preview"->Set.of("settings_change_id");case "restore"->Set.of("settings_change_id","expected_plan_sha256");case "launch"->Set.of("project","configuration_name","dry_run");case "launch_status"->Set.of("debug_launch_id");case "launch_decide"->Set.of("debug_launch_id","choice","expected_decision_sha256");case "stop_owned"->Set.of("project","session_id");default->throw new IllegalArgumentException("Unknown action");};var required=new HashSet<>(fields);if(a.equals("launch")){keys.remove("idempotency_key");keys.remove("decision_policy");}if(!keys.equals(required))throw new IllegalArgumentException("Exact fields required for action: "+fields);Object result;
 if(a.equals("launch")){if(!(p.getRaw().get("dry_run") instanceof Boolean))throw new IllegalArgumentException("dry_run boolean required");if(Boolean.TRUE.equals(p.getRaw().get("dry_run")))result=EdtDebugService.getInstance().launchDebugSession(p.requireString("project"),p.requireString("configuration_name"),true);else{String policy=Objects.toString(p.getRaw().getOrDefault("decision_policy","ask"));if(policy.equals("task_authorized_update"))requireUpdateExposure();result=DebugLaunchRequests.workspace().start(p.requireString("project"),p.requireString("configuration_name"),p.requireString("idempotency_key"),policy);}}
 else if(a.equals("launch_status"))result=DebugLaunchRequests.workspace().status(p.requireString("debug_launch_id"));
 else if(a.equals("launch_decide")){String choice=p.requireString("choice");if(choice.equals("update_and_launch"))requireUpdateExposure();result=DebugLaunchRequests.workspace().decide(p.requireString("debug_launch_id"),p.requireString("expected_decision_sha256"),choice);}
 else if(a.equals("stop_owned")){EdtDebugService.getInstance().closeOwnedDebugSession(p.requireString("project"),p.requireString("session_id"));result=Map.of("closed",true,"session_id",p.requireString("session_id"));}
 else{var service=DebugTargetSettingsService.workspace();result=switch(a){case "list"->EdtDebugService.getInstance().listDebugTargetSettings(p.requireString("project"));case "preview"->service.preview(p.requireString("project"),p.requireString("target_id"),types(p));case "apply"->service.apply(p.requireString("project"),p.requireString("target_id"),types(p),p.requireString("expected_plan_sha256"));case "status"->service.status(p.requireString("settings_change_id"));case "restore_preview"->service.restorePreview(p.requireString("settings_change_id"));case "restore"->service.restore(p.requireString("settings_change_id"),p.requireString("expected_plan_sha256"));default->throw new IllegalArgumentException();};}return ToolResult.success(new Gson().toJson(result));
 }catch(Exception e){Throwable root=e;for(int i=0;i<8&&root.getCause()!=null;i++)root=root.getCause();String reason=com.codepilot1c.core.logging.LogSanitizer.redactSecrets(Objects.toString(root.getMessage(),""));return ToolResult.failure("EDT_DEBUG_TARGETS: "+root.getClass().getSimpleName()+": "+reason.substring(0,Math.min(1024,reason.length())));}});}
 private static List<String> types(ToolParameters p){if(!(p.getRaw().get("types") instanceof List<?> list)||list.stream().anyMatch(v->!(v instanceof String)))throw new IllegalArgumentException("types requires names");return list.stream().map(String.class::cast).toList();}
}
